INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('skeleton_discharges_a_scar_against_an_engine_delta_that_was_never_built', 'Three camera exemptions were recorded as discharged by Δ7, which has zero hits in the renderer and the gate', 'MAJOR', 'peter_parker:field3d_surgeon', 'The #9 skeleton ENGINE DELTA 7 requested camera_gate.exempt_pairs (an authored per-state exemption list) and min_screen_length_frac (a per-taught-segment screen-length floor), and the SAME document then recorded three by-construction-parallel pairs as discharged BY that mechanism: S1 d-hat lying on its own line, S3 the perpendicular segment parallel to n, S8 d1 x d2 measuring 0.00 degrees against the common perpendicular. VG-A/B/C landed and the delta did not: both identifiers return ZERO hits in field_3d_renderer.ts AND in check_vector_geometry_3d.ts. The document reached Checkpoint A DESIGN_OK with the exemptions marked satisfied, so the gap is invisible to anyone reading the skeleton rather than the engine. The skeleton itself named the risk one line later — a pairwise gate with no exemption list either fails every state or gets switched off, and the second is how a gate stops being known to work.', 'A DISCHARGE IS ONLY AS REAL AS THE MECHANISM IT NAMES. A spec that discharges a scar against a REQUESTED engine delta must re-verify that delta EXISTS ON MASTER before the concept is authored against it — a partially-shipped delta silently falsifies every discharger that depends on it. Verify by symbol sweep of the shipped renderer AND its gate, never by the presence of the request in the design document. Corollary: when a multi-delta dispatch lands, diff the SHIPPED delta set against the REQUESTED set and publish the difference, rather than closing the dispatch on the deltas that did land.', 'js_eval', 'Before authoring any concept against a skeleton, extract every delta identifier the skeleton requests and grep the shipped renderer + gate for each; fail the pre-flight if any identifier the skeleton relies on for a DISCHARGE has zero hits. Negative control: assert the probe reports Δ7 absent while reporting Δ1/Δ2/Δ5/Δ6/Δ9/Δ10 present.', 'OPEN', ARRAY['lines_and_planes_in_space', 'vector_products_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts', 'src/scripts/check_vector_geometry_3d.ts']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident'),
('field3d_vg_type_omits_fields_the_scenario_body_reads_so_shipped_behaviour_is_undeclarable', 'Four fields the vg frame driver reads are absent from the vg TypeScript type — the second instance of a class the file itself documents', 'MODERATE', 'peter_parker:field3d_surgeon', 'The per-state vg block type (field_3d_renderer.ts ~:390-517) does not declare scene_group or scene_groups, though the frame driver reads d.scene_groups (:14319) and d.scene_group (:14323, :14333) to drive the Δ10 selector; camera_mode is typed "authored" | "steps" | "auto_frame" (:491) while the driver also dispatches "group" (:14525) reading d.group_cameras (:14532), neither declared. Zod is .passthrough() so a concept authoring them validates and runs — the defect is that the type, which is the authoring CONTRACT, denies the existence of shipped behaviour. This is the SECOND instance of a class this same file documents at :443-452, where the value_readouts union carried only the 11 products tokens while VG_READOUT_LABEL carried 24, making every lines_planes token unauthorable by its own type. That fix was applied to the union it was found in and not swept across the sibling fields in the same block. NOTE: the bug_class the renderer comment cites for the first instance (field3d_vg_value_readouts_type_union_omits_every_lines_planes_token_the_renderer_already_prints) WAS NEVER ACTUALLY FILED — citing a bug_class in a comment does not create it.', 'Every field the scenario body reads from its per-state block is DECLARED in that block type in the SAME change that reads it, and every enum member the body dispatches on is in the declared union. Passthrough validation is not a substitute for a contract: a field that runs but cannot be declared is a field the next author cannot discover. When a type-omission defect is fixed on one field, sweep the whole block — grep the body for d.<name> and for every literal compared against the enum, and diff that set against the declared type.', 'js_eval', 'Parse the vg block type; collect every d.<field> read inside the vg scenario body and every string literal compared against camera_mode; assert the read set is a SUBSET of the declared set and the dispatched enum members are a subset of the declared union. Negative control: assert the probe flags scene_groups and camera_mode "group" against the pre-fix type.', 'OPEN', ARRAY['lines_and_planes_in_space', 'vector_products_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident'),
('vg_lines_planes_segment_readouts_compute_regardless_of_reveal_state', 'A segment readout is computed every frame whether or not its segment has been revealed, so a number can print before its subject exists', 'MODERATE', 'peter_parker:field3d_surgeon', 'In vgResolveLinesPlanes the readout values for segments are computed unconditionally on every frame, independent of the reveal fraction that governs whether the segment is DRAWN. A state that reveals its segment late therefore has a live number available for its panel before the thing the number measures is on screen. This is the same family as the FIXED field3d_vg_a_value_surface_can_disagree_with_the_geometry_it_names (whose third sub-defect was exactly readouts rendering before their subject) and the OPEN vg_state_1_hud_prints_magnitudes_before_either_vector_exists — the reveal-gate was applied to the value_readouts panel and not to the resolver that feeds it. Found during #9 authoring while designing STATE_2 dot-product introduction beat, and worked around there with a verified two-segment recipe rather than relying on reveal ordering.', 'A derived readout is gated by the SAME reveal fraction as the geometry it measures, at the RESOLVER, not only at the panel that prints it. Gating the display surface while the resolver still publishes leaves the number one authoring mistake away from the screen. When a reveal-gate defect is fixed at a display site, apply it at the value SOURCE in the same pass.', 'js_eval', 'For every state, sample the resolver across the state timeline and assert no readout key is populated at any ms where its subject reveal fraction is below 1. Negative control: a segment authored with reveal_at_ms late must produce NO readout value before that ms.', 'OPEN', ARRAY['lines_and_planes_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident'),
('registry_id_fix_applied_to_the_reported_row_and_never_swept_across_the_registry', 'A concept-id divergence was fixed on the row an architect reported and left standing four rows above, orphaning another concept prerequisite edge', 'MODERATE', 'alex:architect', 'mathematicsCatalog.ts:100 declared concept_id "definite_integral_as_area" while the SHIPPED, baseline-locked concept is "definite_integral_as_accumulated_area" (same concept_name, same chapter 8 section 8.1, same class 12, present in visual_baselines). Consequently solids_of_revolution at :144 declared prerequisites ["definite_integral_as_area"] — its ONLY inbound edge — pointing at an id no shipped concept carries. This is the IDENTICAL defect the founder fixed FOUR ROWS BELOW on 2026-08-08 (the vector_dot_and_cross_product divergence), whose own surviving code comment states the correct prevention rule: a concept-id check sweeps the catalog and the registries, not only the concept files. The rule was written and the SWEEP was never run — the fix was applied only to the row an architect happened to be reading for prerequisites. Same shape as the filed vg_state_1_hud_prints_magnitudes_before_either_vector_exists, observed in a registry rather than a renderer. Related OPEN class: call_site_enumeration_asserted_exhaustive_without_a_symbol_sweep. NOTE: the bug_class the skeleton cites as the recorded lesson for this (id_collision_check_scans_the_concept_directories_but_not_the_registry) WAS NEVER FILED.', 'A FIX TO ONE ROW OF A REGISTRY IS RE-RUN AGAINST EVERY ROW OF THAT REGISTRY BEFORE IT IS CLOSED. Writing the prevention rule into a comment beside the single fixed row is not the sweep. Enforce mechanically: every concept_id in a catalog resolves to a shipped concept or is explicitly marked reserved-and-unbuilt, and every prerequisite id resolves to a catalog concept_id — checked for the WHOLE file, not the edited row.', 'js_eval', 'Parse every concept_id and every prerequisites[] entry from mathematicsCatalog.ts; assert each prerequisite resolves to a catalog concept_id, assert no duplicate concept_id, and report every catalog id that is neither shipped nor marked reserved. Verified 2026-08-09 after the fix: 12 concept_ids, 7 prerequisite edges, 0 orphans, 0 duplicates.', 'FIXED', ARRAY['solids_of_revolution', 'definite_integral_as_accumulated_area']::text[], ARRAY['src/lib/mathematicsCatalog.ts']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident'),
('skeleton_asserts_a_sibling_concepts_camera_pose_from_memory_instead_of_reading_its_shipped_json', 'A chapter-seam pose required to be identical was cited at R 9; the sibling shipped JSON says R 16', 'MAJOR', 'alex:architect', 'The #9 skeleton arc rule 5 requires STATE_1 to open on Act I STATE_5 final frame — "same pose, same colours, same objects present" — and sections 5/14 plus FLAG 6 assert that pose is az 90 / el 30 / R 9. Act I own shipped JSON has STATE_5.camera_position = [0.0, 8.0, 13.8564], which is R = 16.0000 exactly (az 90 / el 30 are correct). The apparatus-size half of the reasoning was right (a_mag 3.0, b_mag ramping 2.0 to 2.5 in that exact state) and the radius was inferred from it rather than read. Consequence: STATE_1 entry camera and the camera_steps ease DIRECTION were both wrong — the ease is a pull-IN 16 to 13, not a pull-back 9 to 13 — and every fill / min-pairwise-separation number in the S1 camera row was solved at the wrong radius. The document own FLAG 6 hedged "if the founder reads same pose as including R" — it does; R is part of a pose.', 'A HANDOFF OR CHAPTER-SEAM POSE IS READ FROM THE SIBLING SHIPPED JSON (the camera_position literal), never restated from a survey, a flag, or an earlier round. Matching az and el is NOT evidence that the radius matches — a pose is three numbers and a partial match is the most convincing way to ship the wrong one. Any skeleton claiming continuity with another concept quotes that concept file and line for every number it inherits.', 'manual', 'For any state declaring continuity with another concept frame, assert its authored camera_position equals that concept state camera_position componentwise, read from the sibling JSON at author time.', 'FIXED', ARRAY['lines_and_planes_in_space', 'vector_products_in_space']::text[], ARRAY['docs/skeletons/lines_and_planes_in_space_skeleton.md']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident'),
('skeleton_cites_two_contradictory_values_for_one_measured_event_in_the_same_document', 'One screen-crossing event is cited as t = 0.495 in two sections and t = 0.815 in two others, and re-derivation matches neither', 'MODERATE', 'alex:architect', 'The #9 skeleton states the two skew lines screen images cross at t = 0.495 along line 1 (section 3 control table and the section 14 probe output) and at t = 0.815 along line 1 (section 4 misconception table and section 14 narrative) — the SAME event, the SAME document, two values, neither flagged. Independent closed-form re-derivation at the state own authored pose (R 13 / az 146 / el 4) puts the crossing at s1 = -0.639 raw arc length, about 0.305 of line 1 own sphere-clipped drawn span, matching NEITHER citation under any normalisation tried. The QUALITATIVE claim survives and was re-verified — the two images genuinely do cross, two 3D points 2.805 apart projecting to one pixel — so the state design is sound and only its numbers were wrong. A concept authored from either citation would have placed the misconception marker at a pixel where the lines do not cross, on the state whose entire lesson is that the crossing is an illusion.', 'A measured value is written ONCE in a design document and referenced everywhere else; where it must be restated, the restatements are asserted equal. Two numbers for one event is not a typo class, it is an unverified-measurement class. Any authored marker for a projected coincidence derives from a RECOMPUTED 3D position, never from a cited screen parameter — the 3D point survives a camera change and the parameter does not.', 'manual', 'Extract every numeric claim that appears more than once in a skeleton keyed by the event it describes; assert all occurrences agree. Recompute any value an authored primitive position depends on.', 'FIXED', ARRAY['lines_and_planes_in_space']::text[], ARRAY['docs/skeletons/lines_and_planes_in_space_skeleton.md']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident'),
('vg_intersection_is_a_single_target_so_a_state_teaching_BOTH_cases_can_render_only_one', 'Δ4 no_meeting_point cannot co-exist with an intersection marker, because d.intersection names one line', 'MAJOR', 'peter_parker:field3d_surgeon', 'ENGINE DELTA 4 exists so that the case with NO intersection carries a readout rather than teaching by omission (the recorded state_whose_payoff_is_absence_carries_its_lesson_only_in_on_canvas_prose shape). But d.intersection is a SINGLE OBJECT — var isec = d.intersection (field_3d_renderer.ts:13113) — naming one line and one plane for the whole state. STATE_4 teaches BOTH cases sequentially in one state: the parallel line Lpar (d·n = 0.000) glides past and never touches, then the cutting line Lcut (d·n = 0.574) punches through and the marker snaps on at lambda 2.600. Targeting Lcut makes meet.exists permanently true, so no_meeting_point is permanently false and the Δ4 row can NEVER render. Targeting Lpar renders the absence row but destroys the X marker the state second half requires. There is no authoring of the shipped surface that serves both, so the delta cannot do the job it was requested for on the only state that needs it. Δ4 was specified, reviewed and built against a ONE-LINE mental model of the state while the state design in the same document has two.', 'A readout delta requested to express an ABSENCE must be specified against the STATE that will consume it, including how many subjects that state has co-present. Where a state teaches a contrast between two objects, every per-state singleton in the config (intersection, perpendicular, projection) is checked for arity against that contrast BEFORE the delta is accepted — a singleton silently makes a two-object lesson unauthorable. Fix direction: accept a LIST (intersections[]) keyed by line id, so each line publishes its own d_dot_n / no_meeting_point pair.', 'js_eval', 'For every state authoring more than one line against the same plane, assert each line has an addressable meet result; assert no_meeting_point can be rendered true for one line while intersection_point renders for another in the same state. Negative control: the shipped singleton must FAIL this probe.', 'OPEN', ARRAY['lines_and_planes_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident'),
('vg_lp_plane_ghost_multiplier_applies_to_the_quad_but_not_to_its_normal_arrow', 'A ghosted plane dims its patch and leaves its normal arrow at full brightness', 'MODERATE', 'peter_parker:field3d_surgeon', 'In vgWriteLinesPlanesFrame the plane quad receives the ghost factor — setOpacity(qm, 0.28 * P.ghost) (field_3d_renderer.ts ~:14095) — while the normal ArrowHelper pn[pi] immediately below is given position, direction, length, colour and visible = true with NO ghost term applied (~:14097-14106). A state authoring ghost_at_ms / ghost_opacity on a plane therefore dims the patch and leaves the green normal at full brightness. This directly breaks Rule 32e (exactly ONE glow focal at any instant) for #9 STATE_1, whose choreography is that BOTH the patch and the normal dim to ghosts while keeping their colours so the amber direction arrow becomes the single focal — the state that carries the chapter seam from Act I.', 'A ghost/dim factor applies to EVERY member of the object it names, not only the member that happens to own the opacity call. When an object is composed of a region plus its derived arrow plus their labels, the dim is applied at the group, or each member is enumerated and asserted by a probe — a per-member opacity write is where one member gets silently missed.', 'js_eval', 'Author a plane with ghost_opacity < 1 and show_normal true; assert the normal arrow material opacity equals the quad ghost factor, not 1.0. Extend to the normal label.', 'OPEN', ARRAY['lines_and_planes_in_space']::text[], ARRAY['src/lib/renderers/field_3d_renderer.ts']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident'),
('operating_manual_carveout_names_one_subject_namespace_and_omits_its_identical_sibling', 'CLAUDE.md exempted chemistry from the 8 registration sites and never mentioned mathematics, which has the same isolation contract', 'MODERATE', 'alex:architect', 'CLAUDE.md section 6 "Adding a new concept — EIGHT registration sites (miss one = silent pipeline failure)" carried a parenthetical exempting CHEMISTRY concepts from sites 2/3/4/7/8, and named no other subject. MATHEMATICS has the identical isolation contract (src/data/concepts/mathematics/README.md, docs/MATHEMATICS_ARCHITECTURE.md section 5): mathematics concepts register NOWHERE outside their own directory and are gated by validate:mathematics, which is why the shipped baseline-locked definite_integral_as_accumulated_area appears in ZERO of panelConfig.ts, aiSimulationGenerator.ts and intentClassifier.ts. The canonical operating manual — the file every session is told to read completely and to treat as overriding — therefore instructed an author to make five forbidden edits. The failure mode is inverted from the one the section warns about: not a missed registration, an ADDED one.', 'When a rule carves out one subject namespace, every sibling namespace with the same contract is named in the SAME edit, or the carve-out is written against the CONDITION (a concept outside the flat directory) rather than against one named subject. A rule that enumerates its exceptions by name goes stale the moment a third subject exists.', 'manual', 'For each subject namespace under src/data/concepts/, assert CLAUDE.md registration guidance names it explicitly; assert a shipped concept from each namespace appears in exactly the registration sites its contract permits.', 'FIXED', ARRAY[]::text[], ARRAY['CLAUDE.md']::text[], 'session_2026-08-09_lines_and_planes_bringup', 'incident')
